function libraryFileSize(bytes){return bytes>=1048576?(bytes/1048576).toFixed(1)+' MB':Math.ceil(bytes/1024)+' KB'}
function libraryLinks(r){const files=r.files||[];return files.length?`<div class="library-actions"><a class="primary" href="#rules/${r.documentId}">站内阅读</a>${files.map(f=>`<a class="secondary" href="${f.path}" download>下载${f.format==='PDF原件'?' PDF':'正文'} · ${libraryFileSize(f.bytes)}</a>`).join('')}</div><p class="archive-label">${files.map(f=>`${f.format}${f.pages?' · '+f.pages+' 页':''}`).join(' / ')} · 收录于 ${files[0].archivedAt}</p>`:'<p class="archive-label">正文暂未下载成功，保留官方入口。</p>'}
function documentView(id){
 const r=rules.find(r=>r.documentId===id),file=r?.files?.[0];
 if(!file){rulesView();return}
 app.innerHTML=heading(r.title,'文件保存在本站，可直接阅读和下载。','DOCUMENT READER')+`<a class="secondary" href="#rules">← 返回资料库</a><div class="panel reader-meta"><span class="tag">${r.region}</span> <span class="tag">${r.status}</span><p>版本：${r.version} · 来源：${r.source}<br>文件 / 来源日期：${r.date} · 收录日期：${file.archivedAt}<br>${file.format}${file.pages?' · '+file.pages+' 页':''} · ${libraryFileSize(file.bytes)}</p><div class="library-actions"><a class="primary" href="${file.path}" download>下载文件</a><a class="secondary" href="${file.path}" target="_blank" rel="noopener">在新窗口打开</a><a class="secondary" href="${r.url}" target="_blank" rel="noopener">官方来源 ↗</a></div><p class="archive-label">${file.format==='PDF原件'?'保留官方 PDF 原始字节。':'官方网页正文重新排版留存，未改写条文。'} 历史版本、解读或修订动态请按标注用途阅读。手机若未显示预览，可点击“在新窗口打开”或下载。</p><details><summary>文件校验信息</summary><code class="file-hash">SHA-256：${file.sha256}</code></details></div><iframe class="document-frame" src="${file.path}" title="${r.title}站内阅读" ${file.format==='PDF原件'?'':'sandbox="allow-same-origin allow-popups allow-top-navigation-by-user-activation"'}></iframe>`;
}
